WITH recent_order_items AS (SELECT *, ROUND(unit_price, 2) unit_price_rounded FROM order_items WHERE NOT (quantity BETWEEN 5 AND 6 AND product_id IS NOT NULL AND quantity <> 8)), order_items_stats AS (SELECT product_id, ROUND(STDDEV(unit_price_rounded), 2) stddev_unit_price_rounded FROM recent_order_items GROUP BY product_id) SELECT product_id, stddev_unit_price_rounded FROM order_items_stats ORDER BY stddev_unit_price_rounded DESC;
